import json,hashlib
from pathlib import Path
import numpy as np,pandas as pd
R=Path(__file__).resolve().parents[2];O=R/'outputs'/'round2';O.mkdir(exist_ok=True)
P=json.loads((R/'outputs'/'protocol.json').read_text());parts=[]
for f in sorted((R/'work'/'private').glob('history__QQQ__5__20*.json')):
    d=pd.DataFrame(json.loads(f.read_text()));dt=pd.to_datetime(d.t,unit='s',utc=True).dt.tz_convert('America/New_York');d['day']=dt.dt.strftime('%Y-%m-%d');d['slot']=dt.dt.hour*60+dt.dt.minute-570
    d=d[d.day.isin(P['split']['discovery'])]
    for day,g in d.groupby('day'):
        g=g.sort_values('t').copy();g['y2']=np.log(g.c.shift(-2)/g.c.shift(-1))**2
        g=g[(g.slot>=60)&(g.slot<=375)&(g.t.shift(-2)-g.t==600)].dropna();g['normalized']=g.y2/g.y2.mean();parts.append(g[['day','slot','normalized']])
df=pd.concat(parts);curve=df.groupby('slot').agg(mean=('normalized','mean'),days=('day','nunique')).reset_index();curve.to_csv(O/'discovery-seasonal-profile.csv',index=False)
spec={'frozen_utc':pd.Timestamp.now(tz='UTC').isoformat(),'parent_protocol_sha256':hashlib.sha256((R/'outputs'/'protocol.json').read_bytes()).hexdigest(),'evaluation':'same consumed validation; final remains unscored','feature_history':'r1 squared, mean past 6 squared returns, mean past 12 squared returns; all unchanged across coefficient windows','seasonal_basis':['u=(minutes_since_0930-195)/195','u_squared'],'basis_reason':'Fixed quadratic permits asymmetric opening/closing level and broad curvature with two coefficients; no forced periodic endpoints. Discovery-only normalized intraday curve retained as descriptive support, not a live feature or basis search. No alternatives optimized on validation.','memories_sessions':[20,60],'refit':'once per session using prior-session matured labels','banks':{'unconditional':[],'season':['u','u2'],'state':['r1sq','rv6','rv12'],'state_season':['r1sq','rv6','rv12','u','u2']},'parameter_counts_including_intercept':{'unconditional':1,'season':3,'state':4,'state_season':6},'penalty':'ridge 1, intercept unpenalized; standardization fitted independently on permitted training only','floors':[1e-14,1e-12,1e-10],'primary_floor':1e-12,'mixtures':'equal 20/60 forecasts per bank at each declared floor; no adaptive weights','scores':['MSE of squared-return proxy','QLIKE=log(f)+y2/f'],'inference':'paired mean daily losses, 2000 circular five-session block bootstrap draws; not search-adjusted','episode':'report top-five contributions, best/worst days and monthly losses; keep all eligible days in primary results','positive_link':'not run in initial factorial; if needed, separately freeze new exploratory family before fitting','nvda':{'fix':'Predictor uses current/past NVDA bars only, no NVDA future target mask. QQQ alone determines target observability. Require contiguous historical intervals explicitly.','banks':{'price':['r1','rv6','tod','r6'],'nvda_current':['r1','rv6','tod','nvda_r1'],'nvda_lag5':['r1','rv6','tod','nvda_r1_lag5']},'memories':[20,60],'join':'backward as-of, exact availability match tolerance0; same rows for all banks; +60s assumed release latency','lag':'one additional 5min lag only; no lag grid or future shift','stop':'If all corrected/lagged variants still lose to zero, discontinue this specification; do not use final data for it.'},'seed':20261024,'source_discovery_budget':'At most 12 known date/index public objects plus source code/read-only repository evidence. No auth bypass, no source mutation, no prediction from unidentified quote ages.'}
(O/'protocol.json').write_text(json.dumps(spec,indent=2));print(json.dumps(spec,indent=2));print(curve.groupby(pd.cut(curve.slot,[59,150,270,380])).mean(numeric_only=True).to_string())
